import{_ as e}from"./chunks/CourseWebArticle.vue_vue_type_style_index_0_lang.42cd71f3.js";import{L as d}from"./chunks/LessonQuiz.19ac8c3f.js";import{u as s}from"./chunks/useSourceFidelity.1eac8169.js";import{o as n,c as l,H as t,l as o,k as a,Q as p}from"./chunks/framework.c2383b97.js";const i=`<section data-web-part="0"><div dir="auto" data-markdown-text-style="assistant-message" style="--markdown-link-color: currentColor" data-web-style="s0"><div data-dil-source-message-id="88153fba-d694-48e5-8b62-602c38b40804" data-web-style="s1"><div data-web-style="s2"><div hidden="" data-web-style="s3"></div><div style="--puik-portal-zoom: 1" data-web-style="s2"><div dir="auto" data-d-inline-reveal="" data-d-direction="col" data-dil-message-id="88153fba-d694-48e5-8b62-602c38b40804" data-web-style="s4"><h1 data-d-text-flow="" data-d-component="title" data-d-size="xl" data-d-weight="semibold" data-web-style="s5">📘 第 09 篇：多轮对话与上下文管理——ChatGPT 为什么能记住我们之前聊过的内容？</h1><div data-d-align="center" data-d-component="row" data-d-direction="row" data-d-wrap="wrap" data-web-style="s6"><div data-color="success" data-size="sm" data-pill="" data-variant="soft" data-d-component="badge" data-d-weight="medium" data-web-style="s7">第 09 / 40 篇</div><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">第二阶段：聊天机器人核心原理</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-d-inline="" data-web-style="s9" viewBox="0 0 24 24"><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM12 6C12.5523 6 13 6.44772 13 7V12C13 12.2652 12.8946 12.5196 12.7071 12.7071L10.2071 15.2071C9.81658 15.5976 9.18342 15.5976 8.79289 15.2071C8.40237 14.8166 8.40237 14.1834 8.79289 13.7929L11 11.5858V7C11 6.44772 11.4477 6 12 6Z" fill="currentColor" data-web-style="s10"></path></svg> 阅读约 15–20 分钟</p></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">上一章，我们学习了 Prompt 和 Messages，知道聊天机器人可以通过不同角色的消息组织指令和对话。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">但这里留下了一个重要的问题：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">如果大语言模型本身不会因为普通聊天而持续更新参数，为什么 ChatGPT 还能记住我们前面聊过的内容？甚至在开启新对话后，有时也能记住用户的偏好？</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">答案涉及三个层次：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">模型层：Transformer 如何利用当前上下文。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">应用层：如何保存、裁剪和重新组织历史消息。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">记忆层：如何把重要信息保存下来，并在未来需要时检索。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s11">本篇我们将从原理讲到工程实现，最终使用 TypeScript 设计一个具有多轮对话能力的 AI 聊天机器人。</p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">一、大语言模型本身真的有记忆吗？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">先看一个例子。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">第一轮：</p><blockquote data-d-component="blockquote" data-web-style="s21"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">用户：我是一名前端工程师，目前正在学习 React。</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s11">第二轮：</p><blockquote data-d-component="blockquote" data-web-style="s21"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">用户：它和 Vue 有什么区别？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s11">模型为什么可能知道「它」指 React？</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">因为模型能够利用当前请求中提供的历史上下文。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">但如果我们只发送第二轮问题：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">messages</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> [
  {
    role: </span><span data-web-style="s43">"user"</span><span data-web-style="s40">,
    content: </span><span data-web-style="s43">"它和 Vue 有什么区别？"</span><span data-web-style="s40">
  }
];</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">模型可能无法确定「它」指代什么。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">1.1 模型参数与对话记忆不是一回事</h3><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s48"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto" data-web-style="s49"><tbody data-web-style="s50"><tr data-d-component="table-row" data-web-style="s51"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">概念</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s54"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">保存什么</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">是否跨请求持续存在</p></th></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">模型权重</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">训练中学到的模式和能力</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">是</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">当前上下文</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">本次推理可访问的信息</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">取决于请求</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">KV Cache</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">推理时的中间 K/V 状态</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">取决于缓存生命周期</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">聊天历史</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">用户和助手的历史消息</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">由应用保存</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">长期记忆</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">用户偏好、重要事实等</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">由记忆系统管理</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">所以，<span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">聊天机器人能够记住对话，不等于大语言模型的参数发生了变化。</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">对于常见的无状态聊天 API，每次请求都需要由应用提供相关上下文。某些 API 支持服务端保存会话状态，但本质上仍需要有状态管理机制。</p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">二、多轮对话是如何实现的？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">一个最简单的聊天机器人，可以在每次请求时，把历史消息一起发送给模型。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s60"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">多轮聊天系统的基本架构</span></p><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">React Chat UI</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">发送用户消息、显示历史记录</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Node.js Chat API</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">鉴权、读取会话、组装上下文</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">PostgreSQL / Redis</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">保存消息、会话状态和缓存</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.09);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s66"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">LLM API</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">根据传入的上下文生成回答</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">消息持久化</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">保存回答，供下一轮对话使用</p></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s67">这是简化的顺序示意；实际数据库读取和写入发生在后端请求处理的不同阶段。</span></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">2.1 一次多轮对话的完整流程</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">假设用户发起第三轮对话。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">后端需要：</p><ol data-d-component="list" data-d-marker="number" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s68"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s69"><div data-web-style="s70"><div data-d-list-item-content="" data-web-style="s71"><p data-d-text-flow="" data-d-component="text" data-web-style="s72">根据用户身份验证会话访问权限。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s69"><div data-web-style="s70"><div data-d-list-item-content="" data-web-style="s71"><p data-d-text-flow="" data-d-component="text" data-web-style="s72">从数据库读取相关历史消息。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s69"><div data-web-style="s70"><div data-d-list-item-content="" data-web-style="s71"><p data-d-text-flow="" data-d-component="text" data-web-style="s72">根据上下文窗口限制裁剪或摘要历史。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s69"><div data-web-style="s70"><div data-d-list-item-content="" data-web-style="s71"><p data-d-text-flow="" data-d-component="text" data-web-style="s72">将 System Prompt、历史消息和当前问题组合成 Messages。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s69"><div data-web-style="s70"><div data-d-list-item-content="" data-web-style="s71"><p data-d-text-flow="" data-d-component="text" data-web-style="s72">调用 LLM，并将新回答保存到数据库。</p></div></div></li></ol><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">2.2 TypeScript 示例</h3><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
</span><span data-web-style="s41">type</span><span data-web-style="s40"> </span><span data-web-style="s42">Role</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s43">"user"</span><span data-web-style="s40"> </span><span data-web-style="s41">|</span><span data-web-style="s40"> </span><span data-web-style="s43">"assistant"</span><span data-web-style="s40">;

</span><span data-web-style="s41">interface</span><span data-web-style="s40"> </span><span data-web-style="s42">ChatMessage</span><span data-web-style="s40"> {
  role: </span><span data-web-style="s42">Role</span><span data-web-style="s40">;
  content: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
}

</span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">history</span><span data-web-style="s40">: </span><span data-web-style="s42">ChatMessage</span><span data-web-style="s40">[] </span><span data-web-style="s41">=</span><span data-web-style="s40"> [
  {
    role: </span><span data-web-style="s43">"user"</span><span data-web-style="s40">,
    content: </span><span data-web-style="s43">"我正在学习 React。"</span><span data-web-style="s40">
  },
  {
    role: </span><span data-web-style="s43">"assistant"</span><span data-web-style="s40">,
    content: </span><span data-web-style="s43">"React 是一个 UI 库。"</span><span data-web-style="s40">
  }
];

</span><span data-web-style="s41">function</span><span data-web-style="s40"> </span><span data-web-style="s42">buildMessages</span><span data-web-style="s40">(
  </span><span data-web-style="s42">history</span><span data-web-style="s40">: </span><span data-web-style="s42">ChatMessage</span><span data-web-style="s40">[],
  </span><span data-web-style="s42">question</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">
) {
  </span><span data-web-style="s41">return</span><span data-web-style="s40"> [
    {
      role: </span><span data-web-style="s43">"system"</span><span data-web-style="s40"> </span><span data-web-style="s41">as</span><span data-web-style="s40"> </span><span data-web-style="s41">const</span><span data-web-style="s40">,
      content: </span><span data-web-style="s43">"你是一名前端技术导师。"</span><span data-web-style="s40">
    },
    ...</span><span data-web-style="s42">history</span><span data-web-style="s40">,
    {
      role: </span><span data-web-style="s43">"user"</span><span data-web-style="s40"> </span><span data-web-style="s41">as</span><span data-web-style="s40"> </span><span data-web-style="s41">const</span><span data-web-style="s40">,
      content: </span><span data-web-style="s42">question</span><span data-web-style="s40">
    }
  ];
}

</span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">messages</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s42">buildMessages</span><span data-web-style="s40">(
  </span><span data-web-style="s42">history</span><span data-web-style="s40">,
  </span><span data-web-style="s43">"它和 Vue 有什么区别？"</span><span data-web-style="s40">
);

</span><span data-web-style="s42">console</span><span data-web-style="s41">.</span><span data-web-style="s40">log(</span><span data-web-style="s42">messages</span><span data-web-style="s40">);
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这就是最基础的多轮对话实现方式。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">不过，它会带来一个问题：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">随着聊天轮数增加，历史消息会越来越长。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">三、为什么不能无限发送聊天历史？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">假设用户每轮产生：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">用户输入：100 Tokens。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">AI 回答：400 Tokens。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s11">那么一轮对话约为 500 Tokens。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">当对话达到 100 轮时，历史消息就可能达到：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s73"><span data-web-style="s74"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>100</mn><mo>×</mo><mo stretchy="false">(</mo><mn>100</mn><mo>+</mo><mn>400</mn><mo stretchy="false">)</mo><mo>=</mo><mn>50</mn><mo separator="true">,</mo><mn>000</mn><mtext> Tokens</mtext></mrow><annotation encoding="application/x-tex">100\\times(100+400)=50,000\\ \\text{Tokens}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord">100</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mopen">(</span><span class="mord">100</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord">400</span><span class="mclose">)</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.8889em; vertical-align: -0.1944em;"></span><span class="mord">50</span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord">000</span><span class="mspace"> </span><span class="mord text"><span class="mord">Tokens</span></span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">如果达到 500 轮：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s73"><span data-web-style="s74"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>500</mn><mo>×</mo><mn>500</mn><mo>=</mo><mn>250</mn><mo separator="true">,</mo><mn>000</mn><mtext> Tokens</mtext></mrow><annotation encoding="application/x-tex">500\\times500=250,000\\ \\text{Tokens}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord">500</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">500</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.8889em; vertical-align: -0.1944em;"></span><span class="mord">250</span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord">000</span><span class="mspace"> </span><span class="mord text"><span class="mord">Tokens</span></span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">对于上下文窗口较小的模型，这可能已经超出限制。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">即使没有超限，也可能导致：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">API 成本增加。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">Prefill 时间增加。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">无关历史产生噪声。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">模型遗漏重要信息。</p></div></div></li></ul><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">3.1 交互实验：聊天历史会增长多快？</h3><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s75" data-web-lab="history-growth" data-web-lab-id="history-growth"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">聊天历史 Token 增长模拟器</span></p><div data-d-component="box" data-d-direction="col" data-web-style="s76"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">对话轮数</p><p data-d-text-flow="" data-d-component="text" data-web-style="s79"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12" data-web-range-label="0" data-web-format="{value} 轮">100 轮</span></p></div><input type="range" min="10" max="500" value="100" step="1" aria-label="教程交互参数 1" data-web-range="0" data-web-initial="100" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div><div data-d-component="box" data-d-direction="col" data-web-style="s76"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">每轮用户输入</p><p data-d-text-flow="" data-d-component="text" data-web-style="s79"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12" data-web-range-label="1" data-web-format="{value} Tokens">100 Tokens</span></p></div><input type="range" min="50" max="1000" value="100" step="1" aria-label="教程交互参数 2" data-web-range="1" data-web-initial="100" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div><div data-d-component="box" data-d-direction="col" data-web-style="s76"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">每轮 AI 输出</p><p data-d-text-flow="" data-d-component="text" data-web-style="s79"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12" data-web-range-label="2" data-web-format="{value} Tokens">400 Tokens</span></p></div><input type="range" min="100" max="2000" value="400" step="1" aria-label="教程交互参数 3" data-web-range="2" data-web-initial="400" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">累计历史 Token（估算）</p><h1 data-d-text-flow="" data-d-component="title" data-d-size="2xl" data-d-weight="semibold" data-d-tabular-nums="true" data-web-style="s83" data-web-output="history-total">50,000</h1><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8" data-web-output="history-budget">占示例 128K 上下文窗口的 39.1%</p></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s67">不包含 System Prompt、消息格式开销和其他工具内容。累计历史不等于单次请求一定发送的 Token 数量。</span></div><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">四、上下文管理的四种常见策略</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">为了解决历史消息越来越长的问题，聊天机器人通常需要采用不同的上下文管理策略。</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s48"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto" data-web-style="s49"><tbody data-web-style="s50"><tr data-d-component="table-row" data-web-style="s51"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">策略</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s54"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">核心思想</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">适用场景</p></th></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">全量历史</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">发送所有消息</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">短对话</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">滑动窗口</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">只保留最近若干轮</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">普通聊天</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">历史摘要</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">将较早对话压缩为摘要</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">长时间聊天</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">记忆检索</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">只召回与当前问题相关的信息</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">长期助手</p></td></tr></tbody></table></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">4.1 全量历史（Full History）</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">最简单的方案：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">messages</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> [
  </span><span data-web-style="s42">systemPrompt</span><span data-web-style="s40">,
  ...</span><span data-web-style="s42">allHistory</span><span data-web-style="s40">,
  </span><span data-web-style="s42">currentMessage</span><span data-web-style="s40">
];</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">优点是实现简单、保留的信息完整。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">缺点是成本和上下文占用持续增长。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">4.2 滑动窗口（Sliding Window）</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">只保留最近 N 轮对话。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">第 1 轮：用户询问 React</span>
<span data-web-style="s40">第 2 轮：AI 回答 React</span>
<span data-web-style="s40">第 3 轮：用户询问 Vue</span>
<span data-web-style="s40">第 4 轮：AI 回答 Vue</span>
<span data-web-style="s40">第 5 轮：用户询问状态管理</span>
<span data-web-style="s40">第 6 轮：AI 回答状态管理</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">假设只保留最近两轮完整问答，那么更早的消息将不会被发送给模型。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s75" data-web-lab="sliding-window" data-web-lab-id="sliding-window"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">交互实验：滑动窗口如何裁剪历史？</span></p><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">保留最近完整对话轮数</p><p data-d-text-flow="" data-d-component="text" data-web-style="s79"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12" data-web-range-label="3" data-web-format="{value} 轮">2 轮</span></p></div><input type="range" min="1" max="4" value="2" step="1" aria-label="教程交互参数 4" data-web-range="3" data-web-initial="2" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"><div data-d-component="box" data-d-direction="col" data-web-style="s86"><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s87" data-web-window-row="0" data-web-retained="false"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-web-style="s88">第 1 轮</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s89" data-web-output="window-0">裁剪</p></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">用户：介绍 React</p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">AI：React 是 UI 库</p></div><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s87" data-web-window-row="1" data-web-retained="false"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-web-style="s88">第 2 轮</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s89" data-web-output="window-1">裁剪</p></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">用户：Vue 呢？</p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">AI：Vue 也是 UI 框架</p></div><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--smoothing-background-color: rgba(22,163,74,0.07);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s91" data-web-window-row="2" data-web-retained="true"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-web-style="s88">第 3 轮</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s92" data-web-output="window-2">保留</p></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">用户：状态管理怎么做？</p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">AI：可以使用不同方案</p></div><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--smoothing-background-color: rgba(22,163,74,0.07);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s91" data-web-window-row="3" data-web-retained="true"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s77"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-web-style="s88">第 4 轮</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s92" data-web-output="window-3">保留</p></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">用户：它们如何比较？</p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">AI：需要结合上下文</p></div></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s67">真实应用应按照完整消息及工具调用关系裁剪，避免破坏消息结构。</span></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">4.3 历史摘要（Conversation Summarization）</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">滑动窗口的问题是：重要信息可能被裁剪。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如用户在第一轮说：</p><blockquote data-d-component="blockquote" data-web-style="s21"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">我正在开发一个 React + NestJS 的企业系统。</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s11">后面聊天了 100 轮。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">如果只保留最近 10 轮，这条背景就可能丢失。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">历史摘要可以把较早的对话转换为简短的状态说明：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">对话摘要：</span>
<span data-web-style="s40">用户正在开发 React + NestJS 企业管理系统。</span>
<span data-web-style="s40">用户偏好 TypeScript 示例。</span>
<span data-web-style="s40">当前主要讨论统一鉴权和微前端架构。</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">后续请求可以采用：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">System Prompt</span>
<span data-web-style="s40">     +</span>
<span data-web-style="s40">历史摘要</span>
<span data-web-style="s40">     +</span>
<span data-web-style="s40">最近几轮完整消息</span>
<span data-web-style="s40">     +</span>
<span data-web-style="s40">当前用户问题</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">但摘要也存在信息丢失、错误归纳和过期的问题，因此需要定期更新、校验和管理。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">4.4 记忆检索（Memory Retrieval）</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">另一种方案是将重要信息存储在外部记忆系统中。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">Memory 1：用户主要使用 TypeScript</span>
<span data-web-style="s40">Memory 2：用户正在学习 AI 聊天机器人</span>
<span data-web-style="s40">Memory 3：教程需要包含交互式练习</span>
<span data-web-style="s40">Memory 4：GitHub 页面需要 1:1 还原</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">当用户说：</p><blockquote data-d-component="blockquote" data-web-style="s21"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">继续生成下一篇教程。</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s11">应用可以检索与「教程」相关的记忆，而不是发送所有历史对话。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">不过，记忆的存储、更新和检索都需要独立设计，不能假设模型天然拥有无限长期记忆。</p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">五、短期记忆与长期记忆有什么区别？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">这是 AI 聊天机器人架构设计中的重要概念。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">我们可以将记忆分成三个层次：</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s60"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">聊天机器人记忆系统</span></p><div data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s93"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">工作记忆（Working Memory）</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">当前请求中的 Messages、工具结果、上下文信息</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(22,163,74,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s94"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">会话记忆（Session Memory）</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">当前会话的完整消息、摘要与任务状态</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s95"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">长期记忆（Long-term Memory）</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">跨会话保存的偏好、重要事实、项目规则与历史经验</p></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s67">这是工程设计中的概念划分，不是所有 AI 产品都采用完全相同的记忆架构。</span></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">5.1 工作记忆</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">工作记忆就是模型当前能够访问的信息。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">messages</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> [
  {
    role: </span><span data-web-style="s43">"system"</span><span data-web-style="s40">,
    content: </span><span data-web-style="s43">"你是前端技术导师。"</span><span data-web-style="s40">
  },
  {
    role: </span><span data-web-style="s43">"user"</span><span data-web-style="s40">,
    content: </span><span data-web-style="s43">"React 和 Vue 有什么区别？"</span><span data-web-style="s40">
  }
];</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这段内容只说明当前请求中提供了什么。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">工作记忆并不等于永久存储。</span></p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">5.2 会话记忆</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">会话记忆由应用负责维护。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如数据库中保存：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">Conversation ID: chat_001</span>
<span data-web-style="s40"></span>
<span data-web-style="s40">Message 1: 用户询问 React</span>
<span data-web-style="s40">Message 2: AI 介绍 React</span>
<span data-web-style="s40">Message 3: 用户询问 Vue</span>
<span data-web-style="s40">Message 4: AI 比较 React 和 Vue</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">当用户刷新页面后，前端可以根据 Conversation ID 重新读取历史。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这里要区分两件事：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">恢复聊天界面</span>：从数据库读取消息并展示。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">让模型利用历史</span>：把相关消息重新提供给模型，或使用支持服务端会话状态的 API。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s11">两者不是同一回事。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">5.3 长期记忆</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">长期记忆通常保存跨会话仍然有用的信息。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">JSON</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">{
  "userId": </span><span data-web-style="s43">"user_001"</span><span data-web-style="s40">,
  "memories": [
    {
      "type": </span><span data-web-style="s43">"preference"</span><span data-web-style="s40">,
      "content": </span><span data-web-style="s43">"优先使用 TypeScript 示例"</span><span data-web-style="s40">
    },
    {
      "type": </span><span data-web-style="s43">"project_rule"</span><span data-web-style="s40">,
      "content": </span><span data-web-style="s43">"教程同步 GitHub 必须 1:1 还原"</span><span data-web-style="s40">
    }
  ]
}</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">以后用户开启新的对话，应用可以检索这些信息并注入上下文。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">但长期记忆也不能无限保存所有内容。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">实际系统需要考虑记忆的相关性、时效性、准确性、用户控制权和隐私保护。</p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">六、长期记忆如何实现？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">一个常见的实现方案是：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">关系型数据库 + Embedding + 语义检索。</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如使用 PostgreSQL 和 pgvector。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s60"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">长期记忆的写入与读取</span></p><div data-d-component="grid" data-web-style="s96"><div data-d-component="grid-item" data-d-direction="col" data-d-variant="transparent" style="--grid-item-column: auto;--grid-item-row: auto" data-web-style="s97"><div data-d-component="box" data-d-direction="col" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-d-text-align="center" data-web-style="s98">写入记忆</p><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2);padding-block: calc(var(--spacing, 0.25rem) * 2);padding-inline: calc(var(--spacing, 0.25rem) * 2)" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-d-weight="medium" data-web-style="s100">用户对话</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s101" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s102"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2);padding-block: calc(var(--spacing, 0.25rem) * 2);padding-inline: calc(var(--spacing, 0.25rem) * 2)" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-d-weight="medium" data-web-style="s100">提取重要事实</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s101" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s102"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2);padding-block: calc(var(--spacing, 0.25rem) * 2);padding-inline: calc(var(--spacing, 0.25rem) * 2)" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-d-weight="medium" data-web-style="s100">Embedding</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s101" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s102"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2);padding-block: calc(var(--spacing, 0.25rem) * 2);padding-inline: calc(var(--spacing, 0.25rem) * 2)" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-d-weight="medium" data-web-style="s100">记忆数据库</p></div></div></div><div data-d-component="grid-item" data-d-direction="col" data-d-variant="transparent" style="--grid-item-column: auto;--grid-item-row: auto" data-web-style="s97"><div data-d-component="box" data-d-direction="col" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-d-text-align="center" data-web-style="s98">读取记忆</p></div></div></div></div></div></div></div></div></div></section>
<section data-web-part="1"><div dir="auto" data-markdown-text-style="assistant-message" style="--markdown-link-color: currentColor" data-web-style="s0"><div data-dil-source-message-id="4bc25b25-1b87-4f29-8459-01e3a2a4feb8" data-web-style="s1"><div data-web-style="s2"><div hidden="" data-web-style="s3"></div><div style="--puik-portal-zoom: 1" data-web-style="s2"><div dir="auto" data-d-inline-reveal="" data-d-direction="col" data-dil-message-id="4bc25b25-1b87-4f29-8459-01e3a2a4feb8" data-web-style="s4"><h1 data-d-text-flow="" data-d-component="title" data-d-size="xl" data-d-weight="semibold" data-web-style="s5">📘 第 09 篇（下）：多轮对话与上下文管理</h1><div data-d-align="center" data-d-component="row" data-d-direction="row" data-d-wrap="wrap" data-web-style="s6"><div data-color="success" data-size="sm" data-pill="" data-variant="soft" data-d-component="badge" data-d-weight="medium" data-web-style="s7">第 09 / 40 篇</div><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">第二部分 · 第五至十二节</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-d-inline="" data-web-style="s9" viewBox="0 0 24 24"><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM12 6C12.5523 6 13 6.44772 13 7V12C13 12.2652 12.8946 12.5196 12.7071 12.7071L10.2071 15.2071C9.81658 15.5976 9.18342 15.5976 8.79289 15.2071C8.40237 14.8166 8.40237 14.1834 8.79289 13.7929L11 11.5858V7C11 6.44772 11.4477 6 12 6Z" fill="currentColor" data-web-style="s10"></path></svg> 阅读约 12–15 分钟</p></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">前四节，我们学习了聊天历史的基本原理，以及全量历史、滑动窗口、历史摘要和记忆检索四种策略。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">接下来，我们将进一步研究：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">ChatGPT 为什么能够跨会话记住用户偏好？长期记忆如何设计？怎样使用 TypeScript 实现一个真正支持多轮对话的聊天机器人？</span></p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">五、短期记忆与长期记忆有什么区别？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">在聊天机器人系统中，通常可以将记忆分为两类。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">5.1 短期记忆（Short-term Memory）</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">短期记忆主要服务于当前会话。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">用户：我正在学习 React。</span>
<span data-web-style="s40">AI：好的，我们从基础开始。</span>
<span data-web-style="s40"></span>
<span data-web-style="s40">用户：它和 Vue 有什么区别？</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">第二轮中的「它」需要依赖第一轮的信息。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">因此，应用需要保留相关消息。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">短期记忆通常包括：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">最近几轮对话。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">当前任务状态。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">临时变量与工具结果。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">当前会话的上下文摘要。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这些内容通常与某个 <code data-d-component="code" data-web-style="s103">conversationId</code> 关联。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">5.2 长期记忆（Long-term Memory）</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">长期记忆则用于保存跨会话仍然有价值的信息。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">用户偏好：</span>
<span data-web-style="s40">- 主要使用 TypeScript</span>
<span data-web-style="s40">- 喜欢中文技术教程</span>
<span data-web-style="s40">- 每篇教程需要交互实验</span>
<span data-web-style="s40">- GitHub 必须尽量 1:1 还原</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">当用户开启新对话时，应用可以在获得适当授权后检索这些信息，并作为上下文提供给模型。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">5.3 两者的核心区别</h3><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s48"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto" data-web-style="s49"><tbody data-web-style="s50"><tr data-d-component="table-row" data-web-style="s51"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">维度</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s54"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">短期记忆</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">长期记忆</p></th></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">作用范围</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">当前会话</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">跨会话</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">保存内容</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">聊天历史、任务状态</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">偏好、重要事实</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">存储方式</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">会话数据库、缓存</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">持久化数据库、向量库</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">生命周期</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">通常较短</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">通常较长</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">检索方式</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">按会话读取</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">关键词、语义、结构化查询</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">主要问题</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s58"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">上下文过长</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">记忆过期、冲突、隐私</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这里有一个重要区别：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">长期记忆不是把全部聊天记录永久放进 Prompt，而是在需要时取出相关信息。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">六、长期记忆如何存储与检索？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">假设我们正在开发一个 AI 学习助手。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">用户曾经说过：</p><blockquote data-d-component="blockquote" data-web-style="s21"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">我是一名前端工程师，主要使用 TypeScript，希望教程包含交互实验。</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s11">应用可以将其整理成结构化记忆。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">6.1 记忆的数据结构</h3><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
</span><span data-web-style="s41">interface</span><span data-web-style="s40"> </span><span data-web-style="s42">Memory</span><span data-web-style="s40"> {
  id: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  userId: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  category:
    </span><span data-web-style="s41">|</span><span data-web-style="s40"> </span><span data-web-style="s43">"preference"</span><span data-web-style="s40">
    </span><span data-web-style="s41">|</span><span data-web-style="s40"> </span><span data-web-style="s43">"fact"</span><span data-web-style="s40">
    </span><span data-web-style="s41">|</span><span data-web-style="s40"> </span><span data-web-style="s43">"project"</span><span data-web-style="s40">;
  content: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  createdAt: </span><span data-web-style="s42">number</span><span data-web-style="s40">;
  updatedAt: </span><span data-web-style="s42">number</span><span data-web-style="s40">;
  sourceConversationId?: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
}
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">例如：</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">JSON</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
{
  "id": </span><span data-web-style="s43">"memory_001"</span><span data-web-style="s40">,
  "userId": </span><span data-web-style="s43">"user_123"</span><span data-web-style="s40">,
  "category": </span><span data-web-style="s43">"preference"</span><span data-web-style="s40">,
  "content": </span><span data-web-style="s43">"用户偏好中文 TypeScript 技术教程"</span><span data-web-style="s40">,
  "createdAt": </span><span data-web-style="s104">1760000000000</span><span data-web-style="s40">,
  "updatedAt": </span><span data-web-style="s104">1760000000000</span><span data-web-style="s40">,
  "sourceConversationId": </span><span data-web-style="s43">"conversation_001"</span><span data-web-style="s40">
}
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">真实系统还应该考虑记忆来源、有效期、用户删除权限以及敏感信息的处理策略。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">6.2 记忆如何进入 Prompt？</h3><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s60"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">长期记忆检索架构</span></p><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">用户发送问题</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">继续生成 AI 聊天机器人教程</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Memory Retriever</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">检索与当前问题相关的用户记忆</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(22,163,74,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s105"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Memory Filter</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">权限检查、去重、冲突与有效期判断</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Context Builder</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">组合系统指令、记忆、历史和当前问题</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">LLM</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">基于可用上下文生成回答</p></div></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">6.3 记忆一定需要向量数据库吗？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">不一定。</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s48"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto" data-web-style="s49"><tbody data-web-style="s50"><tr data-d-component="table-row" data-web-style="s51"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">记忆类型</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">推荐存储方案</p></th></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">用户语言偏好</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">PostgreSQL 字段</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">当前项目 ID</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">关系型数据库</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">最近聊天记录</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">PostgreSQL / Redis</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">大量自然语言记忆</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">向量检索或混合检索</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">任务进度</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">结构化状态表</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">如果只有几十条明确的用户偏好，使用 PostgreSQL 就足够了。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">当记忆数量很大、需要根据语义查找相关信息时，才更有必要引入 Embedding 和向量检索。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">6.4 交互实验：记忆检索</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">尝试切换用户问题，观察哪些记忆会被选中。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s75" data-web-lab="memory-retrieval"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">记忆检索模拟器</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="记忆检索问题" data-d-component="radio-group" style="outline: none" data-web-style="s106"><div data-d-component="radio" data-web-style="s107"><label for="生成下一篇 AI 教程-_r_o3f_" data-web-style="s108"><div data-web-style="s109"><input type="radio" name="web-lesson-9-memory-query" value="0" id="生成下一篇 AI 教程-_r_o3f_" checked style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>生成下一篇 AI 教程</label></div><div data-d-component="radio" data-web-style="s107"><label for="写一段 React TypeScript 代码-_r_o3h_" data-web-style="s108"><div data-web-style="s109"><input type="radio" name="web-lesson-9-memory-query" value="1" id="写一段 React TypeScript 代码-_r_o3h_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>写一段 React TypeScript 代码</label></div><div data-d-component="radio" data-web-style="s107"><label for="解释 RAG 和 Embedding-_r_o3j_" data-web-style="s108"><div data-web-style="s109"><input type="radio" name="web-lesson-9-memory-query" value="2" id="解释 RAG 和 Embedding-_r_o3j_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>解释 RAG 和 Embedding</label></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle);--divider-size: 1px" data-web-style="s112"></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-web-style="s88">检索结果</p><div data-d-align="center" data-d-component="row" data-d-direction="row" data-web-style="s113" data-web-memory-row="0" data-web-matched="false"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s114" viewBox="0 0 6 6" data-web-memory-icon=""><rect width="6" height="6" rx="3" data-web-style="s115"></rect></svg><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">用户主要使用 TypeScript 和 React</p></div><div data-d-align="center" data-d-component="row" data-d-direction="row" data-web-style="s113" data-web-memory-row="1" data-web-matched="true"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s116" viewBox="0 0 24 24" data-web-memory-icon=""><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM16.0755 7.93219C16.5272 8.25003 16.6356 8.87383 16.3178 9.32549L11.5678 16.0755C11.3931 16.3237 11.1152 16.4792 10.8123 16.4981C10.5093 16.517 10.2142 16.3973 10.0101 16.1727L7.51006 13.4227C7.13855 13.014 7.16867 12.3816 7.57733 12.0101C7.98598 11.6386 8.61843 11.6687 8.98994 12.0773L10.6504 13.9039L14.6822 8.17451C15 7.72284 15.6238 7.61436 16.0755 7.93219Z" fill="currentColor" data-web-style="s117"></path></svg><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">用户喜欢中文文字教程</p></div><div data-d-align="center" data-d-component="row" data-d-direction="row" data-web-style="s113" data-web-memory-row="2" data-web-matched="true"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s116" viewBox="0 0 24 24" data-web-memory-icon=""><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM16.0755 7.93219C16.5272 8.25003 16.6356 8.87383 16.3178 9.32549L11.5678 16.0755C11.3931 16.3237 11.1152 16.4792 10.8123 16.4981C10.5093 16.517 10.2142 16.3973 10.0101 16.1727L7.51006 13.4227C7.13855 13.014 7.16867 12.3816 7.57733 12.0101C7.98598 11.6386 8.61843 11.6687 8.98994 12.0773L10.6504 13.9039L14.6822 8.17451C15 7.72284 15.6238 7.61436 16.0755 7.93219Z" fill="currentColor" data-web-style="s117"></path></svg><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s78">AI 教程同步 GitHub 时需要 1:1 还原</p></div><div data-d-align="center" data-d-component="row" data-d-direction="row" data-web-style="s113" data-web-memory-row="3" data-web-matched="false"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s114" viewBox="0 0 6 6" data-web-memory-icon=""><rect width="6" height="6" rx="3" data-web-style="s115"></rect></svg><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s90">用户正在研究 RAG 和 Embedding</p></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s67">这是关键词规则模拟，不是真实的 Embedding 语义检索。实际记忆系统需要结合相关性、权限和有效期进行排序。</span></div><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">七、TypeScript 实现多轮对话管理器</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">现在进入工程实践。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">我们先实现一个不依赖框架的简单对话管理器，支持：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">保存聊天消息。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">读取历史消息。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">通过 Token 预算裁剪。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">组合 System Prompt 和当前问题。</p></div></div></li></ul><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">7.1 定义消息类型</h3><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
</span><span data-web-style="s41">type</span><span data-web-style="s40"> </span><span data-web-style="s42">ChatRole</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s43">"user"</span><span data-web-style="s40"> </span><span data-web-style="s41">|</span><span data-web-style="s40"> </span><span data-web-style="s43">"assistant"</span><span data-web-style="s40">;

</span><span data-web-style="s41">interface</span><span data-web-style="s40"> </span><span data-web-style="s42">ChatMessage</span><span data-web-style="s40"> {
  id: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  role: </span><span data-web-style="s42">ChatRole</span><span data-web-style="s40">;
  content: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  createdAt: </span><span data-web-style="s42">number</span><span data-web-style="s40">;
}

</span><span data-web-style="s41">interface</span><span data-web-style="s40"> </span><span data-web-style="s42">Conversation</span><span data-web-style="s40"> {
  id: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  userId: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
  messages: </span><span data-web-style="s42">ChatMessage</span><span data-web-style="s40">[];
}
</span></code></pre></div></div></div></div></div></div></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">7.2 实现 ConversationManager</h3><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
</span><span data-web-style="s41">class</span><span data-web-style="s40"> </span><span data-web-style="s104">ConversationManager</span><span data-web-style="s40"> {
  </span><span data-web-style="s41">private</span><span data-web-style="s40"> conversations </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s41">new</span><span data-web-style="s40"> </span><span data-web-style="s42">Map</span><span data-web-style="s40">&lt;
    </span><span data-web-style="s42">string</span><span data-web-style="s40">,
    </span><span data-web-style="s42">Conversation</span><span data-web-style="s40">
  &gt;();

  create(
    </span><span data-web-style="s42">conversationId</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">,
    </span><span data-web-style="s42">userId</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">
  ) {
    </span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">conversation</span><span data-web-style="s40">: </span><span data-web-style="s42">Conversation</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> {
      id: </span><span data-web-style="s42">conversationId</span><span data-web-style="s40">,
      userId,
      messages: []
    };

    </span><span data-web-style="s104">this</span><span data-web-style="s41">.</span><span data-web-style="s40">conversations</span><span data-web-style="s41">.</span><span data-web-style="s40">set(
      </span><span data-web-style="s42">conversationId</span><span data-web-style="s40">,
      </span><span data-web-style="s42">conversation</span><span data-web-style="s40">
    );

    </span><span data-web-style="s41">return</span><span data-web-style="s40"> </span><span data-web-style="s42">conversation</span><span data-web-style="s40">;
  }

  addMessage(
    </span><span data-web-style="s42">conversationId</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">,
    </span><span data-web-style="s42">message</span><span data-web-style="s40">: </span><span data-web-style="s42">ChatMessage</span><span data-web-style="s40">
  ) {
    </span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">conversation</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40">
      </span><span data-web-style="s104">this</span><span data-web-style="s41">.</span><span data-web-style="s40">conversations</span><span data-web-style="s41">.</span><span data-web-style="s40">get(</span><span data-web-style="s42">conversationId</span><span data-web-style="s40">);

    </span><span data-web-style="s41">if</span><span data-web-style="s40"> (</span><span data-web-style="s41">!</span><span data-web-style="s42">conversation</span><span data-web-style="s40">) {
      </span><span data-web-style="s41">throw</span><span data-web-style="s40"> </span><span data-web-style="s41">new</span><span data-web-style="s40"> </span><span data-web-style="s104">Error</span><span data-web-style="s40">(</span><span data-web-style="s43">"Conversation not found"</span><span data-web-style="s40">);
    }

    </span><span data-web-style="s42">conversation</span><span data-web-style="s41">.</span><span data-web-style="s40">messages</span><span data-web-style="s41">.</span><span data-web-style="s40">push(</span><span data-web-style="s42">message</span><span data-web-style="s40">);
  }

  getHistory(
    </span><span data-web-style="s42">conversationId</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">,
    </span><span data-web-style="s42">userId</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">
  ) {
    </span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">conversation</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40">
      </span><span data-web-style="s104">this</span><span data-web-style="s41">.</span><span data-web-style="s40">conversations</span><span data-web-style="s41">.</span><span data-web-style="s40">get(</span><span data-web-style="s42">conversationId</span><span data-web-style="s40">);

    </span><span data-web-style="s41">if</span><span data-web-style="s40"> (</span><span data-web-style="s41">!</span><span data-web-style="s42">conversation</span><span data-web-style="s40"> </span><span data-web-style="s41">||</span><span data-web-style="s40">
        </span><span data-web-style="s42">conversation</span><span data-web-style="s41">.</span><span data-web-style="s40">userId </span><span data-web-style="s41">!==</span><span data-web-style="s40"> </span><span data-web-style="s42">userId</span><span data-web-style="s40">) {
      </span><span data-web-style="s41">throw</span><span data-web-style="s40"> </span><span data-web-style="s41">new</span><span data-web-style="s40"> </span><span data-web-style="s104">Error</span><span data-web-style="s40">(</span><span data-web-style="s43">"Conversation not found"</span><span data-web-style="s40">);
    }

    </span><span data-web-style="s41">return</span><span data-web-style="s40"> [...</span><span data-web-style="s42">conversation</span><span data-web-style="s41">.</span><span data-web-style="s40">messages];
  }
}
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这段代码用于说明基本的数据结构。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">生产环境不能依赖进程内 <code data-d-component="code" data-web-style="s103">Map</code> 保存全部会话，因为服务重启会丢失数据，多实例之间也无法共享状态。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">实际项目应将会话和消息持久化到数据库。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">另外，写入消息时也需要校验用户是否有权访问对应会话。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">7.3 根据 Token 预算裁剪消息</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">我们可以设计一个通用函数。</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">TypeScript</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
</span><span data-web-style="s41">interface</span><span data-web-style="s40"> </span><span data-web-style="s42">Message</span><span data-web-style="s40"> {
  role: </span><span data-web-style="s43">"user"</span><span data-web-style="s40"> </span><span data-web-style="s41">|</span><span data-web-style="s40"> </span><span data-web-style="s43">"assistant"</span><span data-web-style="s40">;
  content: </span><span data-web-style="s42">string</span><span data-web-style="s40">;
}

</span><span data-web-style="s41">function</span><span data-web-style="s40"> </span><span data-web-style="s42">trimHistory</span><span data-web-style="s40">(
  </span><span data-web-style="s42">history</span><span data-web-style="s40">: </span><span data-web-style="s42">Message</span><span data-web-style="s40">[],
  </span><span data-web-style="s42">maxTokens</span><span data-web-style="s40">: </span><span data-web-style="s42">number</span><span data-web-style="s40">,
  </span><span data-web-style="s42">countTokens</span><span data-web-style="s40">: (</span><span data-web-style="s42">text</span><span data-web-style="s40">: </span><span data-web-style="s42">string</span><span data-web-style="s40">) =&gt; </span><span data-web-style="s42">number</span><span data-web-style="s40">
): </span><span data-web-style="s42">Message</span><span data-web-style="s40">[] {
  </span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">result</span><span data-web-style="s40">: </span><span data-web-style="s42">Message</span><span data-web-style="s40">[] </span><span data-web-style="s41">=</span><span data-web-style="s40"> [];
  </span><span data-web-style="s41">let</span><span data-web-style="s40"> </span><span data-web-style="s42">usedTokens</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s104">0</span><span data-web-style="s40">;

  </span><span data-web-style="s41">for</span><span data-web-style="s40"> (</span><span data-web-style="s41">let</span><span data-web-style="s40"> </span><span data-web-style="s42">i</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s42">history</span><span data-web-style="s41">.</span><span data-web-style="s40">length </span><span data-web-style="s41">-</span><span data-web-style="s40"> </span><span data-web-style="s104">1</span><span data-web-style="s40">; </span><span data-web-style="s42">i</span><span data-web-style="s40"> </span><span data-web-style="s41">&gt;=</span><span data-web-style="s40"> </span><span data-web-style="s104">0</span><span data-web-style="s40">; </span><span data-web-style="s42">i</span><span data-web-style="s41">--</span><span data-web-style="s40">) {
    </span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">message</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s42">history</span><span data-web-style="s40">[</span><span data-web-style="s42">i</span><span data-web-style="s40">];
    </span><span data-web-style="s41">const</span><span data-web-style="s40"> </span><span data-web-style="s42">tokens</span><span data-web-style="s40"> </span><span data-web-style="s41">=</span><span data-web-style="s40"> </span><span data-web-style="s42">countTokens</span><span data-web-style="s40">(</span><span data-web-style="s42">message</span><span data-web-style="s41">.</span><span data-web-style="s40">content);

    </span><span data-web-style="s41">if</span><span data-web-style="s40"> (</span><span data-web-style="s42">usedTokens</span><span data-web-style="s40"> </span><span data-web-style="s41">+</span><span data-web-style="s40"> </span><span data-web-style="s42">tokens</span><span data-web-style="s40"> </span><span data-web-style="s41">&gt;</span><span data-web-style="s40"> </span><span data-web-style="s42">maxTokens</span><span data-web-style="s40">) {
      </span><span data-web-style="s41">break</span><span data-web-style="s40">;
    }

    </span><span data-web-style="s42">result</span><span data-web-style="s41">.</span><span data-web-style="s40">unshift(</span><span data-web-style="s42">message</span><span data-web-style="s40">);
    </span><span data-web-style="s42">usedTokens</span><span data-web-style="s40"> </span><span data-web-style="s41">+=</span><span data-web-style="s40"> </span><span data-web-style="s42">tokens</span><span data-web-style="s40">;
  }

  </span><span data-web-style="s41">return</span><span data-web-style="s40"> </span><span data-web-style="s42">result</span><span data-web-style="s40">;
}
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这里的 <code data-d-component="code" data-web-style="s103">countTokens</code> 需要使用与目标模型兼容的 Tokenizer 或计数接口实现。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">还需要注意，这个简化函数仅统计文本内容，没有计算消息元数据和工具调用开销。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">对于带工具调用的会话，还必须保证裁剪后的消息结构合法。</p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">八、React + Node.js 聊天系统架构</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">如果要开发一个真正可用的聊天机器人，建议采用分层设计。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s60"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">生产级聊天系统架构（简化版）</span></p><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s118"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">React Chat UI</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">聊天列表 / 输入框 / 流式渲染</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Node.js / NestJS API</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">鉴权 / 限流 / 会话路由</p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-component="grid" data-web-style="s96"><div data-d-component="grid-item" data-d-direction="col" data-d-variant="transparent" style="--grid-item-column: auto;--grid-item-row: auto" data-web-style="s97"><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Conversation Service</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">消息管理与历史裁剪</p></div></div><div data-d-component="grid-item" data-d-direction="col" data-d-variant="transparent" style="--grid-item-column: auto;--grid-item-row: auto" data-web-style="s97"><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s62"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">Memory Service</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" data-web-style="s8">长期记忆检索</p></div></div></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s63"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-web-style="s64" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s65"></path></svg></div><div data-d-component="grid" data-web-style="s96"><div data-d-component="grid-item" data-d-direction="col" data-d-variant="transparent" style="--grid-item-column: auto;--grid-item-row: auto" data-web-style="s97"><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(22,163,74,0.08);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s119"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">LLM API</span></p></div></div><div data-d-component="grid-item" data-d-direction="col" data-d-variant="transparent" style="--grid-item-column: auto;--grid-item-row: auto" data-web-style="s97"><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary);--w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3);--w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3);padding-block: calc(var(--spacing, 0.25rem) * 3);padding-inline: calc(var(--spacing, 0.25rem) * 3)" data-web-style="s120"><p data-d-text-flow="" data-d-component="text" data-web-style="s61"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">PostgreSQL / Redis</span></p></div></div></div></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">8.1 数据库应该如何设计？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">一个基础聊天系统至少可以设计两张表。</p><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">SQL</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s35"><div data-web-style="s36"><div dir="ltr" data-web-style="s37"><div data-web-style="s38"><pre data-web-style="s39"><code data-web-style="s40"><span data-web-style="s40">
</span><span data-web-style="s41">CREATE</span><span data-web-style="s40"> </span><span data-web-style="s41">TABLE</span><span data-web-style="s40"> conversations (
  id UUID </span><span data-web-style="s41">PRIMARY</span><span data-web-style="s40"> </span><span data-web-style="s41">KEY</span><span data-web-style="s40">,
  user_id UUID </span><span data-web-style="s41">NOT</span><span data-web-style="s40"> </span><span data-web-style="s104">NULL</span><span data-web-style="s40">,
  title TEXT,
  created_at TIMESTAMPTZ </span><span data-web-style="s41">DEFAULT</span><span data-web-style="s40"> NOW(),
  updated_at TIMESTAMPTZ </span><span data-web-style="s41">DEFAULT</span><span data-web-style="s40"> NOW()
);

</span><span data-web-style="s41">CREATE</span><span data-web-style="s40"> </span><span data-web-style="s41">TABLE</span><span data-web-style="s40"> messages (
  id UUID </span><span data-web-style="s41">PRIMARY</span><span data-web-style="s40"> </span><span data-web-style="s41">KEY</span><span data-web-style="s40">,
  conversation_id UUID </span><span data-web-style="s41">NOT</span><span data-web-style="s40"> </span><span data-web-style="s104">NULL</span><span data-web-style="s40">
    </span><span data-web-style="s41">REFERENCES</span><span data-web-style="s40"> conversations(id),
  </span><span data-web-style="s41">role</span><span data-web-style="s40"> </span><span data-web-style="s42">VARCHAR</span><span data-web-style="s40">(</span><span data-web-style="s104">20</span><span data-web-style="s40">) </span><span data-web-style="s41">NOT</span><span data-web-style="s40"> </span><span data-web-style="s104">NULL</span><span data-web-style="s40">,
  content TEXT </span><span data-web-style="s41">NOT</span><span data-web-style="s40"> </span><span data-web-style="s104">NULL</span><span data-web-style="s40">,
  created_at TIMESTAMPTZ </span><span data-web-style="s41">DEFAULT</span><span data-web-style="s40"> NOW()
);

</span><span data-web-style="s41">CREATE</span><span data-web-style="s40"> INDEX idx_messages_conversation
</span><span data-web-style="s41">ON</span><span data-web-style="s40"> messages(conversation_id, created_at);
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">这只是基础版本。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">生产环境还需要考虑消息状态、工具调用记录、消息顺序、幂等性、删除策略和多租户隔离。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">8.2 为什么要使用 Redis？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">Redis 可以用于：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">缓存最近聊天历史。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">保存临时任务状态。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">请求限流。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">分布式锁或其他协调机制。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s11">但 Redis 不一定要承担全部持久化职责。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">对于需要长期保存的聊天记录，通常应使用可靠的持久化存储。</p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">九、生产级上下文管理与性能优化</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">一个生产级聊天机器人不能只追求「记住得多」，还需要平衡准确性、成本、延迟和隐私。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">9.1 推荐的上下文组织方式</h3><div data-web-style="s22"><div data-web-style="s23"><div data-code-block="true" data-search-result-target="" data-web-style="s24" data-web-code=""><div data-web-style="s25"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s26" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s28">纯文本</div><div data-web-style="s29"><div data-code-block-controls="true" role="presentation" data-web-style="s30"><span data-web-style="s31"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s32" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s31"><button type="button" aria-label="复制代码" data-web-style="s32" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s33" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s84"><code data-web-style="s85"><span data-web-style="s40"><span data-web-style="s40">System Prompt</span>
<span data-web-style="s40">      +</span>
<span data-web-style="s40">用户长期记忆（经过相关性筛选）</span>
<span data-web-style="s40">      +</span>
<span data-web-style="s40">历史对话摘要</span>
<span data-web-style="s40">      +</span>
<span data-web-style="s40">最近几轮完整消息</span>
<span data-web-style="s40">      +</span>
<span data-web-style="s40">当前用户问题</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">但这不是固定公式。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">不同任务需要不同策略。例如代码调试更依赖最近的错误日志，而长期学习助手可能更依赖用户目标和学习进度。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">9.2 需要重点监控的指标</h3><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s48"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto" data-web-style="s49"><tbody data-web-style="s50"><tr data-d-component="table-row" data-web-style="s51"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">指标</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">作用</p></th></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Input Tokens</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">衡量上下文成本</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">TTFT</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">衡量首字响应延迟</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Memory Hit Rate</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">衡量记忆召回情况</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Retrieval Relevance</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">评估检索相关性</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Context Truncation Rate</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">观察历史裁剪频率</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Answer Quality</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">评估回答正确性</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11">记忆命中率越高，不一定代表回答越好。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s11">错误或过期记忆被频繁召回，反而可能降低回答质量。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s47">9.3 长期记忆的安全与隐私</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s20">长期记忆还需要考虑：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0)" data-web-style="s13"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">用户是否同意保存。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">用户能否查看和更正记忆。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">用户能否删除记忆。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">敏感信息是否需要禁止存储。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">记忆是否设置有效期。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s14"><div data-web-style="s15"><div data-d-list-item-content="" data-web-style="s16"><p data-d-text-flow="" data-d-component="text" data-web-style="s17">多用户之间是否存在数据隔离。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">长期记忆是一项产品能力，同时也是数据治理责任。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">十、本篇总结</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">本篇最重要的知识可以归纳为：</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s48"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto" data-web-style="s49"><tbody data-web-style="s50"><tr data-d-component="table-row" data-web-style="s51"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">概念</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-web-style="s53">核心作用</p></th></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Chat History</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">保存历史消息</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Context Window</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">限制模型单次可处理的内容</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Sliding Window</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">保留最近对话</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Summarization</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">压缩较早历史</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Short-term Memory</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">管理当前会话状态</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Long-term Memory</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">保存跨会话重要信息</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Memory Retrieval</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">按需召回相关记忆</p></td></tr><tr data-d-component="table-row" data-web-style="s51"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s56"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">Conversation Manager</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s59"><p data-d-text-flow="" data-d-component="text" data-web-style="s57">组织消息与会话状态</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s11"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s12">最重要的一句话：聊天机器人之所以能够记住用户，不是因为每次聊天都会重新训练模型，而是因为应用能够保存、检索和重新提供相关上下文。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border);--divider-size: 1px" data-web-style="s18"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s19">十一、交互式课后测验</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s20">这次设计了 5 道选择题，支持提交评分、查看正确答案与解析、重新作答。</p></div></div></div></div></div></section>`;const w=a("div",{class:"info custom-block"},[a("p",{class:"custom-block-title"},"本地补充练习与解答"),a("p",null,"提供的 09.htm 在第十一节的测验介绍后结束，没有保存实际题目及第十二节。以下保留原有本地的五道练习题和学习解答，供学习自测与参考。")],-1),r=p('<h2 id="学习疑问与解答-本地补充" tabindex="-1">学习疑问与解答（本地补充） <a class="header-anchor" href="#学习疑问与解答-本地补充" aria-label="Permalink to &quot;学习疑问与解答（本地补充）&quot;">​</a></h2><h3 id="q1-恢复聊天界面-为什么不等于让模型知道历史" tabindex="-1">Q1：恢复聊天界面，为什么不等于让模型知道历史？ <a class="header-anchor" href="#q1-恢复聊天界面-为什么不等于让模型知道历史" aria-label="Permalink to &quot;Q1：恢复聊天界面，为什么不等于让模型知道历史？&quot;">​</a></h3><p>恢复 UI 是从数据库读取消息并渲染 React；让模型利用历史，则需要在推理请求中提供相关消息，或使用支持服务端会话状态的 API。两条流程的服务对象不同。</p><h3 id="q2-短期记忆与长期记忆分别适合什么数据库" tabindex="-1">Q2：短期记忆与长期记忆分别适合什么数据库？ <a class="header-anchor" href="#q2-短期记忆与长期记忆分别适合什么数据库" aria-label="Permalink to &quot;Q2：短期记忆与长期记忆分别适合什么数据库？&quot;">​</a></h3><p>会话历史可存 PostgreSQL、MySQL、MongoDB 或 SQLite；Redis 可用于热点会话缓存。长期结构化记忆可存 PostgreSQL，语义检索可用 pgvector、Qdrant、Milvus 等。</p><h3 id="q3-postgresql-是向量数据库吗" tabindex="-1">Q3：PostgreSQL 是向量数据库吗？ <a class="header-anchor" href="#q3-postgresql-是向量数据库吗" aria-label="Permalink to &quot;Q3：PostgreSQL 是向量数据库吗？&quot;">​</a></h3><p>PostgreSQL 本质是关系型数据库。安装 pgvector 扩展后，可以在同一数据库中存储 Embedding 向量并执行相似度检索。初期 AI 聊天机器人推荐 PostgreSQL + pgvector；确有性能需求再加 Redis。</p><h3 id="q4-为什么长期记忆不应该直接等于全部聊天记录" tabindex="-1">Q4：为什么长期记忆不应该直接等于全部聊天记录？ <a class="header-anchor" href="#q4-为什么长期记忆不应该直接等于全部聊天记录" aria-label="Permalink to &quot;Q4：为什么长期记忆不应该直接等于全部聊天记录？&quot;">​</a></h3><p>聊天历史可能包含无关、过期或敏感内容。长期记忆应按价值、授权、有效期与相关性筛选，并提供查看、更正和删除机制。</p><h3 id="q5-kv-cache-是不是长期记忆" tabindex="-1">Q5：KV Cache 是不是长期记忆？ <a class="header-anchor" href="#q5-kv-cache-是不是长期记忆" aria-label="Permalink to &quot;Q5：KV Cache 是不是长期记忆？&quot;">​</a></h3><p>不是。KV Cache 是模型推理时复用的 Key/Value 中间状态，不是面向用户偏好和项目事实的持久化记忆库。</p>',11),u=JSON.parse('{"title":"09 · 多轮对话与上下文管理","description":"","frontmatter":{"title":"09 · 多轮对话与上下文管理","outline":"deep","readingTime":"20","courseMeta":false},"headers":[],"relativePath":"guide/ai/chatbot-course/09-conversation-memory.md","filePath":"guide/ai/chatbot-course/09-conversation-memory.md","lastUpdated":1792546820000}'),c={name:"guide/ai/chatbot-course/09-conversation-memory.md"},f=Object.assign(c,{setup(b){return s(9),(y,v)=>(n(),l("div",null,[t(e,{source:o(i),chapter:9},null,8,["source"]),w,t(d,{chapter:9}),r]))}});export{u as __pageData,f as default};
